#!/usr/bin/env python3
from pwn import *
import time

# Connect to the server
def connect_to_server():
    return remote('misc.chal.csaw.io', 5000)

def get_num_qubits(io):
    # Read initial output until we get the number of qubits
    while True:
        line = io.recvline().decode().strip()
        if "qubits" in line:
            try:
                return int(line.split()[0])
            except:
                continue

def measure_bases(io, bases):
    # Send measurement bases
    io.sendline(''.join(map(str, bases)).encode())

    # Get the response
    while True:
        line = io.recvline().decode().strip()
        if "correct" in line:
            try:
                return int(line.split()[0])
            except:
                continue
    return 0

def optimize_measurements(num_qubits):
    io = connect_to_server()
    log.info(f"Connected to server")

    # Get number of qubits
    num_qubits = get_num_qubits(io)
    log.info(f"Number of qubits: {num_qubits}")

    # Start with all zeros
    best_bases = [0] * num_qubits
    best_correct = measure_bases(io, best_bases)
    log.info(f"Initial measurement (all 0s): {best_correct}/{num_qubits} correct")

    # Try flipping each position
    for pos in range(num_qubits):
        test_bases = best_bases.copy()
        test_bases[pos] = 1

        correct = measure_bases(io, test_bases)
        log.info(f"Testing position {pos}: {correct}/{num_qubits} correct")

        if correct > best_correct:
            best_bases = test_bases
            best_correct = correct
            log.info(f"Improvement found! New best: {best_correct}/{num_qubits}")
        else:
            log.info(f"No improvement, keeping original value")

        # Check if we've found all correct measurements
        if best_correct == num_qubits:
            log.success(f"Found all correct measurements!")
            break

    io.close()
    return best_bases, best_correct

def main():
    context.log_level = 'info'
    log.info("Starting quantum measurement optimization")

    try:
        best_bases, best_correct = optimize_measurements(10)
        log.success(f"Best result: {best_correct} correct measurements")
        log.success(f"Best bases: {''.join(map(str, best_bases))}")
    except Exception as e:
        log.error(f"Error occurred: {str(e)}")

if __name__ == "__main__":
    main()

