from pwn import *
import time
import string

# Configure logging
context.log_level = 'info'

class QKDSolver:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.bases = ['0', '1', '2', '3', '4']  # Reduced to 5 bases
        self.best_pattern = None
        self.best_errors = float('inf')

    def connect_with_retry(self):
        for attempt in range(3):
            try:
                conn = remote(self.host, self.port)
                return conn
            except Exception as e:
                log.warning(f"Connection attempt {attempt + 1} failed: {e}")
                if attempt < 2:
                    time.sleep(2)
                else:
                    raise

    def get_error_count(self, pattern):
        try:
            conn = self.connect_with_retry()

            # Receive initial prompt and number of qubits
            initial = conn.recvuntil(b"number of qubits: ")
            conn.sendline(pattern.encode())

            # Get error count
            response = conn.recvline().decode().strip()
            conn.close()

            if "incorrect" in response.lower():
                errors = int(response.split()[2])
                return errors
            elif "flag" in response.lower():
                # Found the flag!
                log.success(f"Found flag: {response}")
                return 0
            else:
                raise ValueError(f"Unexpected response: {response}")

        except Exception as e:
            log.error(f"Error during measurement: {e}")
            return float('inf')

    def try_pattern(self, pattern):
        errors = self.get_error_count(pattern)
        log.info(f"Pattern {pattern} got {errors} errors")
        return errors

    def optimize_pattern(self, n_qubits):
        # Start with all zeros
        self.best_pattern = '0' * n_qubits
        self.best_errors = self.try_pattern(self.best_pattern)
        log.info(f"Initial pattern: {self.best_pattern}, Errors: {self.best_errors}")

        # Try all ones
        all_ones = '1' * n_qubits
        errors = self.try_pattern(all_ones)
        if errors < self.best_errors:
            self.best_pattern = all_ones
            self.best_errors = errors

        # Binary search optimization
        for i in range(n_qubits):
            # Try flipping each position
            test_pattern = list(self.best_pattern)
            for base in self.bases:
                if base == self.best_pattern[i]:
                    continue

                test_pattern[i] = base
                current = ''.join(test_pattern)
                errors = self.try_pattern(current)

                if errors < self.best_errors:
                    self.best_pattern = current
                    self.best_errors = errors
                    log.success(f"Found better pattern: {self.best_pattern}, Errors: {self.best_errors}")

                if self.best_errors == 0:
                    return

    def solve(self):
        try:
            # Get number of qubits first
            conn = self.connect_with_retry()
            initial = conn.recvuntil(b"number of qubits: ").decode()
            n_qubits = int(initial.split()[-4])
            conn.close()

            log.info(f"Need to measure {n_qubits} qubits")
            self.optimize_pattern(n_qubits)

        except Exception as e:
            log.error(f"Fatal error: {e}")

def main():
    solver = QKDSolver('misc.chal.csaw.io', 5000)
    solver.solve()

if __name__ == '__main__':
    main()

